    '[{"id":"ks-p1","name":"The Royal Surakarta Heritage Hotel","category":"hotel","image":"https://images.unsplash.com/photo-1566073771259-6a8506099945?q=80&w=600","rating":4.7,"price":"IDR 900,000 / night","distance":"1.5 km","description":"Luxury heritage hotel in the heart of Solo, walking distance from the Keraton.","address":"Jl. Slamet Riyadi, Surakarta"}]'::jsonb,
